template <class P>
iterator insert(P&& x)  // SFINAE constraint: This overload participates only if std::is_constructible<value_type, P&&>::value is true.
{
    return emplace(std::forward<P>(x));  // Perfect forwarding preserves the value category of x for efficient construction.
}

template <class P>
iterator insert(const_iterator position, P&& x)  // SFINAE constraint: Same as above.
{
    return emplace_hint(position, std::forward<P>(x));  // Uses the hint for potential optimization in tree insertion.
}
